#include <stdio.h>

int main() {
    int numbers[] = {12, 45, 3, 89, 27, 56};
    int n = sizeof(numbers) / sizeof(numbers[0]);
    int largest = numbers[0];

    for (int i = 1; i < n; i++) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    printf("Largest number: %d\n", largest);
    return 0;
}
